def get_identity_stat_weights(slot_key,*,item_subtype="",armor_type=""):
 """Resolve a fail-closed weighted profile from the persisted item identity."""
 slot=str(slot_key or "");subtype=str(item_subtype or "");armor=str(armor_type or "")
 if slot=="main_hand":profile=WEAPON_STAT_WEIGHTS.get(subtype)
 elif slot=="off_hand":profile=OFF_HAND_STAT_WEIGHTS.get(subtype)
 elif slot in ("necklace","ring"):profile=JEWELRY_STAT_WEIGHTS
 elif slot in ("helmet","shoulders","chest","gloves","legs","boots"):profile=ARMOR_STAT_WEIGHTS.get(armor)
 else:profile=None
 if not profile:raise ValueError(f"Unsupported equipment identity: slot={slot!r}, subtype={subtype!r}, armor_type={armor!r}")
 return profile

def redistribute_identity_primary_stats(stats,slot_key,*,item_subtype="",armor_type="",chooser):
 """Redistribute existing positive primary-stat chunks without changing budget."""
 if not callable(chooser):raise TypeError("chooser must be callable")
 profile=get_identity_stat_weights(slot_key,item_subtype=item_subtype,armor_type=armor_type)
 result=dict(stats);chunks=[]
 for stat in PRIMARY_STATS:
  value=int(result.get(BONUS_KEYS[stat],0) or 0)
  if value>0:chunks.append(value)
  result[BONUS_KEYS[stat]]=0
 for value in chunks:
  selected=str(chooser(profile)).strip().lower()
  if selected not in dict(profile):raise ValueError(f"Chooser returned invalid stat: {selected!r}")
  key=BONUS_KEYS[selected];result[key]=int(result.get(key,0) or 0)+value
 return result

def validate_identity_stat_policy():
 errors=[]
 expected={"sword_1h","sword_2h","dagger_1h","wand_1h","staff_2h","bow_2h","crossbow_2h"}
 if set(WEAPON_STAT_WEIGHTS)!=expected:errors.append("weapon subtype set mismatch")
 if set(OFF_HAND_STAT_WEIGHTS)!={"warrior_shield","shield","dagger","talisman"}:errors.append("off-hand subtype set mismatch")
 if set(ARMOR_STAT_WEIGHTS)!={"cloth","leather","chain","plate"}:errors.append("armor type set mismatch")
 for label,profiles in (("weapon",WEAPON_STAT_WEIGHTS),("off_hand",OFF_HAND_STAT_WEIGHTS),("armor",ARMOR_STAT_WEIGHTS)):
  for key,profile in profiles.items():
   if sum(weight for _stat,weight in profile)!=100:errors.append(f"{label}.{key}: weights must total 100")
   if any(stat not in PRIMARY_STATS or weight<=0 for stat,weight in profile):errors.append(f"{label}.{key}: invalid profile")
 if set(stat for stat,_weight in JEWELRY_STAT_WEIGHTS)!=set(PRIMARY_STATS) or len({weight for _stat,weight in JEWELRY_STAT_WEIGHTS})!=1:errors.append("jewelry must be universal equal-weight")
 return tuple(errors)

def normalize_equipment_class(class_key: object) -> str:
    key = str(class_key or "").strip().lower()
    if key not in SUPPORTED_CLASSES:
        raise ValueError(f"Unsupported equipment target class: {class_key!r}")
    return key

def _validate_weight_profile(profile: object, label: str) -> tuple[tuple[str, int], ...]:
    if not isinstance(profile, tuple) or not profile:
        raise ValueError(f"{label}: profile must be a non-empty tuple")
    seen = set()
    total = 0
    normalized = []
    for entry in profile:
        if not isinstance(entry, tuple) or len(entry) != 2:
            raise ValueError(f"{label}: invalid weighted entry {entry!r}")
        stat_key, weight = entry
        if stat_key not in PRIMARY_STATS or stat_key in seen:
            raise ValueError(f"{label}: invalid or duplicate stat {stat_key!r}")
        if isinstance(weight, bool) or not isinstance(weight, int) or weight <= 0:
            raise ValueError(f"{label}: invalid weight for {stat_key}: {weight!r}")
        seen.add(stat_key)
        total += weight
        normalized.append((stat_key, weight))
    if total != 100:
        raise ValueError(f"{label}: weights total {total}, expected 100")
    return tuple(normalized)

def get_equipment_stat_weights(
    class_key: object,
    equipment_kind: str,
    *,
    item_subtype: str = "",
) -> tuple[tuple[str, int], ...]:
    """Return immutable weighted primary-stat choices for one target class."""
    cls = normalize_equipment_class(class_key)
    kind = str(equipment_kind or "").strip().lower()
    subtype = str(item_subtype or "").strip().lower()
    if kind not in SUPPORTED_EQUIPMENT_KINDS:
        raise ValueError(f"Unsupported equipment kind: {equipment_kind!r}")
    if kind == "weapon":
        if subtype and subtype not in CLASS_MAIN_HAND_SUBTYPES[cls]:
            raise ValueError(f"Main-hand subtype {subtype!r} is not allowed for {cls}")
        profile = MAIN_HAND_STAT_WEIGHTS[cls]
    elif kind == "armor":
        profile = ARMOR_STAT_WEIGHTS[cls]
    elif kind == "jewelry":
        profile = JEWELRY_STAT_WEIGHTS[cls]
    else:
        if subtype not in CLASS_OFF_HAND_SUBTYPES[cls]:
            raise ValueError(f"Off-hand subtype {subtype!r} is not allowed for {cls}")
        profile = OFF_HAND_STAT_WEIGHTS[(cls, subtype)]
    return _validate_weight_profile(profile, f"{cls}:{kind}:{subtype or '*'}")

def validate_equipment_stat_policy() -> tuple[str, ...]:
    problems = []
    expected_classes = set(SUPPORTED_CLASSES)
    for label, mapping in (
        ("CLASS_STAT_WEIGHTS", CLASS_STAT_WEIGHTS),
        ("MAIN_HAND_STAT_WEIGHTS", MAIN_HAND_STAT_WEIGHTS),
        ("JEWELRY_STAT_WEIGHTS", JEWELRY_STAT_WEIGHTS),
        ("CLASS_ARMOR_TYPES", CLASS_ARMOR_TYPES),
        ("CLASS_MAIN_HAND_SUBTYPES", CLASS_MAIN_HAND_SUBTYPES),
        ("CLASS_OFF_HAND_SUBTYPES", CLASS_OFF_HAND_SUBTYPES),
    ):
        if set(mapping) != expected_classes:
            problems.append(f"{label}: class set mismatch")
    for cls in SUPPORTED_CLASSES:
        for kind in ("weapon", "armor", "jewelry"):
            try:
                profile = get_equipment_stat_weights(cls, kind)
                _validate_weight_profile(profile, f"{cls}:{kind}")
            except Exception as error:
                problems.append(str(error))
        for subtype in CLASS_OFF_HAND_SUBTYPES[cls]:
            try:
                get_equipment_stat_weights(cls, "off_hand", item_subtype=subtype)
            except Exception as error:
                problems.append(str(error))
    if get_allowed_equipment_stats("knight", "off_hand", item_subtype="shield") != ("sta", "str"):
        problems.append("Knight shield must allow exactly STA and STR")
    return tuple(problems)

def redistribute_primary_stat_budget(stats, class_key, equipment_kind, *, item_subtype="", chooser):
    """Redistribute existing positive primary-stat chunks by canonical class policy.

    The total primary-stat budget and number of generated chunks are preserved.
    `chooser` receives the immutable weighted profile and returns one stat key.
    """
    if not callable(chooser):
        raise ValueError("chooser must be callable")
    profile = get_equipment_stat_weights(class_key, equipment_kind, item_subtype=item_subtype)
    allowed = {stat for stat, _weight in profile}
    result = dict(stats)
    chunks = []
    for stat_key in PRIMARY_STATS:
        column = "bonus_" + stat_key
        value = int(result.get(column, 0) or 0)
        if value > 0:
            chunks.append(value)
        result[column] = 0
    if not chunks:
        return result
    for value in chunks:
        selected = str(chooser(profile) or "").strip().lower()
        if selected not in allowed:
            raise ValueError(f"chooser returned forbidden stat {selected!r}")
        column = "bonus_" + selected
        result[column] = int(result.get(column, 0) or 0) + value
    if sum(int(result.get("bonus_" + stat, 0) or 0) for stat in PRIMARY_STATS) != sum(chunks):
        raise ValueError("primary-stat budget changed during redistribution")
    return result

def _decimal(value: Any, field_name: str) -> Decimal:
    """Return a finite Decimal while rejecting bool and malformed input."""
    if isinstance(value, bool) or value is None:
        raise ManaPolicyError(f"{field_name} must be a finite number, not {value!r}")
    if isinstance(value, float) and not isfinite(value):
        raise ManaPolicyError(f"{field_name} must be finite")
    try:
        result = Decimal(str(value))
    except (InvalidOperation, ValueError, TypeError) as error:
        raise ManaPolicyError(f"{field_name} must be a finite number") from error
    if not result.is_finite():
        raise ManaPolicyError(f"{field_name} must be finite")
    return result

def _non_negative_decimal(value: Any, field_name: str) -> Decimal:
    result = _decimal(value, field_name)
    if result < 0:
        raise ManaPolicyError(f"{field_name} must not be negative")
    return result

def _non_negative_int(value: Any, field_name: str) -> int:
    number = _non_negative_decimal(value, field_name)
    if number != number.to_integral_value():
        raise ManaPolicyError(f"{field_name} must be an integer")
    return int(number)

def round_mana_value(value: Any) -> int:
    """Round a non-negative Mana value with explicit half-up semantics."""
    number = _non_negative_decimal(value, "value")
    return int(number.quantize(Decimal("1"), rounding=ROUND_HALF_UP))

def validate_mana_skill_definition(skill: Mapping[str, Any]) -> dict[str, Decimal]:
    """Validate and normalize the future hybrid-cost contract of one Mana skill."""
    if not isinstance(skill, Mapping):
        raise ManaPolicyError("skill must be a mapping")
    if str(skill.get("cost_type") or "") != "mana":
        raise ManaPolicyError("skill cost_type must be 'mana'")
    missing = [
        field for field in (MANA_COST_FLAT_FIELD, MANA_COST_MAX_MP_PERCENT_FIELD)
        if field not in skill
    ]
    if missing:
        raise ManaPolicyError("missing Mana cost fields: " + ", ".join(missing))
    normalized = {
        MANA_COST_FLAT_FIELD: _non_negative_decimal(
            skill[MANA_COST_FLAT_FIELD], MANA_COST_FLAT_FIELD
        ),
        MANA_COST_MAX_MP_PERCENT_FIELD: _non_negative_decimal(
            skill[MANA_COST_MAX_MP_PERCENT_FIELD], MANA_COST_MAX_MP_PERCENT_FIELD
        ),
    }
    if MANA_RESTORE_MAX_MP_PERCENT_FIELD in skill:
        normalized[MANA_RESTORE_MAX_MP_PERCENT_FIELD] = _non_negative_decimal(
            skill[MANA_RESTORE_MAX_MP_PERCENT_FIELD],
            MANA_RESTORE_MAX_MP_PERCENT_FIELD,
        )
    return normalized

def calculate_mana_restore_amount(max_mp: Any, percent: Any) -> int:
    """Return a clamped nominal percentage restoration amount."""
    maximum = _non_negative_int(max_mp, "max_mp")
    restore_percent = _non_negative_decimal(percent, "percent")
    amount = round_mana_value(Decimal(maximum) * restore_percent / Decimal("100"))
    return min(maximum, amount)

def calculate_post_combat_mp_floor(
    max_mp: Any,
    percent: Any = MANA_POST_COMBAT_FLOOR_CURRENT_PERCENT,
) -> int:
    """Return the active canonical 50% post-combat Mana floor."""
    return calculate_mana_restore_amount(max_mp, percent)

def apply_post_combat_mp_floor_value(
    current_mp: Any,
    max_mp: Any,
    percent: Any = MANA_POST_COMBAT_FLOOR_CURRENT_PERCENT,
) -> int:
    """Apply a floor without adding it and without exceeding Max MP."""
    maximum = _non_negative_int(max_mp, "max_mp")
    current = min(_non_negative_int(current_mp, "current_mp"), maximum)
    return max(current, calculate_post_combat_mp_floor(maximum, percent))

def calculate_passive_mp_regen_per_full_minute(max_mp: Any) -> int:
    """Return the unchanged 30% per-full-minute passive regeneration tick."""
    return calculate_mana_restore_amount(max_mp, MANA_REGEN_PERCENT_PER_FULL_MINUTE)

def _calculate_crit_chance_with_soft_cap(total_stat):
    stat = float(total_stat or 0)
    if stat <= CRIT_SOFT_CAP_TRANSITION_STAT:
        return CRIT_BASE_CHANCE + max(0.0, stat - CRIT_STAT_BASELINE) * CRIT_PER_STAT
    excess = stat - CRIT_SOFT_CAP_TRANSITION_STAT
    return CRIT_SOFT_CAP_TRANSITION_CHANCE + CRIT_SOFT_CAP_RANGE * excess / (excess + CRIT_SOFT_CAP_K)

def calculate_dodge_chance(defender_dex, attacker_dex):
    dex_delta = float(defender_dex or 0) - float(attacker_dex or 0)
    if dex_delta <= -20.0:
        return DODGE_MIN_CHANCE
    if dex_delta <= DODGE_SOFT_CAP_TRANSITION_DELTA:
        return DODGE_BASE_CHANCE + dex_delta * DODGE_PER_DEX_DELTA
    excess = dex_delta - DODGE_SOFT_CAP_TRANSITION_DELTA
    return DODGE_SOFT_CAP_TRANSITION_CHANCE + DODGE_SOFT_CAP_RANGE * excess / (excess + DODGE_SOFT_CAP_K)

def calculate_base_max_hp(level, total_stamina):
    """Return base max HP before percentage modifiers such as armor refine."""
    safe_level = max(1, int(level or DEFAULT_STARTING_LEVEL))
    safe_stamina = max(0, int(total_stamina or 0))
    return max(1, STARTING_HP_BASE + safe_level * HP_PER_LEVEL + safe_stamina * HP_PER_STAMINA)

def get_rune_definition(item_id):
    try:
        return RUNE_ITEM_DEFINITIONS.get(int(item_id))
    except Exception:
        return None

def get_rune_item_id(stat, level):
    try:
        return RUNE_ITEM_ID_BY_KEY.get((str(stat).strip().upper(), int(level)))
    except Exception:
        return None

def round_stat(value: object) -> int:
    number = _number(value, "value")
    return int(math.floor(number + 0.5))

def validate_class_scaling(candidate: Mapping[str, Mapping[str, Mapping[str, object]]]) -> None:
    if set(candidate) != set(SUPPORTED_CLASSES):
        raise ValueError("candidate must define exactly the six supported classes")
    for class_key in SUPPORTED_CLASSES:
        entry = candidate[class_key]
        if set(entry) != {"patk", "matk"}:
            raise ValueError(f"{class_key} must define patk and matk")
        for attack_kind in ("patk", "matk"):
            coefficients = entry[attack_kind]
            if not coefficients:
                raise ValueError(f"{class_key}.{attack_kind} must not be empty")
            for stat_name, coefficient in coefficients.items():
                if stat_name not in SUPPORTED_STATS:
                    raise ValueError(f"unsupported stat: {stat_name}")
                _number(coefficient, f"{class_key}.{attack_kind}.{stat_name}")

def _calculate_attack(
    class_key: object,
    stats: Mapping[str, object],
    attack_kind: str,
    candidate: Mapping[str, Mapping[str, Mapping[str, object]]],
) -> int:
    validate_class_scaling(candidate)
    normalized = normalize_class_key(class_key)
    if normalized not in candidate:
        identity_stat = "str" if attack_kind == "patk" else "int"
        return round_stat(_number(stats.get(identity_stat, 0), identity_stat))
    total = 0.0
    for stat_name, coefficient in candidate[normalized][attack_kind].items():
        total += _number(stats.get(stat_name, 0), stat_name) * _number(coefficient, f"coefficient.{stat_name}")
    return max(0, round_stat(total))

def calc_max_hp_parity(level: object, total_sta: object, refine_percent: object = 0.0) -> int:
    from data.player_hp import calculate_base_max_hp
    base_hp = calculate_base_max_hp(round_stat(level), round_stat(total_sta))
    multiplier = 1.0 + _number(refine_percent, "refine_percent") / 100.0
    return max(1, round_stat(base_hp * multiplier))

def calc_pdef_parity(item_pdef: object, total_sta: object) -> int:
    from data.defense_policy import calculate_total_defense
    return int(calculate_total_defense(_number(item_pdef, "item_pdef"), _number(total_sta, "total_sta")))

def calc_mdef_parity(item_mdef: object, total_wis: object) -> int:
    from data.defense_policy import calculate_total_defense
    return int(calculate_total_defense(_number(item_mdef, "item_mdef"), _number(total_wis, "total_wis")))

def resolve_story_quest_presentation_title(quest, status: str, quest_item_quantity: int = 0) -> str:
    """Return a neutral title until a hidden quest item is actually acquired."""
    if quest.quest_type is not QuestType.QUEST_ITEM:
        return str(quest.title)
    state = str(status or "LOCKED").upper()
    if state in {"COMPLETED", "SKIPPED"}:
        return str(quest.title)
    item = quest.quest_item
    required = int(item.required_quantity) if item is not None else int(quest.target_quantity)
    if int(quest_item_quantity or 0) >= max(1, required):
        return str(quest.title)
    return str(PRE_REVEAL_TITLE_BY_QUEST_ID.get(quest.quest_id, quest.title))

