            text, kb = build_alchemist_sell_preview_17_19_3(user_id, int(parts[2]), 1)
        elif parts[1] == 'sellset':
            text, kb = build_alchemist_sell_preview_17_19_3(user_id, int(parts[2]), int(parts[3]))
