                "type": "shield",
                "turns": 3,
                "absorb_left": absorb_amount,
                "modifiers": {}
            }
        )

        text += f"🧱 Святий захист створив щит на {absorb_amount} шкоди на 3 ходи.\n"

    elif effect_key == "enemy_pdef_trap":
