            mob,
            "scout_trap_pdef_down",
            {
                "name": "🪤 Пастка",
                "type": "debuff",
                "turns": 2,
                "modifiers": {
                    "pdef_percent": -50
                }
            }
        )

        text += f"🪤 {mob['name']} потрапив у пастку: фізичний захист знижено на 50% на 2 ходи.\n"

    elif effect_key == "enemy_bleed":
        bleed_damage = max(
            2,
