 return d

def build_standard_actor(cls,level=10,rarity="rare",uid=1,class_damage=1.0):
 if cls not in CLASSES or rarity not in RARITIES: raise ValueError("unsupported class/rarity")
 inv=SimulationInventory(capacity=40); eq=SimulationEquipment(); n=1
 for slot in SLOTS:
  item=SimulationInventoryItem(simulation_item_id=n,item_id=100000+n,name=f"{LABELS[cls]} {slot}",category="equipment",slot_key=slot,rarity=rarity,quantity=1,durability=100,refine_level=0,stats=_stats(cls,slot,level,rarity))
  inv.items.append(item); eq.slots[slot]=item.simulation_item_id; n+=1
 s=build_combat_stat_snapshot(cls,level,inv,eq); mana=s.resource_type=="mana"
 atk=round(s.attack*class_damage); matk=round(s.magic_attack*class_damage); wmin=round(s.weapon_min_damage*class_damage); wmax=round(s.weapon_max_damage*class_damage)
 return PvpActorState(user_id=uid,class_key=cls,character_name=LABELS[cls],max_hp=s.max_hp,hp=s.max_hp,max_mp=s.max_mp,mp=s.max_mp,resource_type=s.resource_type,resource=0 if s.resource_type=="rage" else (s.max_mp if mana else 100),combo=0,physical_attack=atk,magical_attack=matk,physical_defense=s.pdef,magical_defense=s.mdef,weapon_physical_min=0 if mana else wmin,weapon_physical_max=0 if mana else wmax,weapon_magical_min=wmin if mana else 0,weapon_magical_max=wmax if mana else 0,physical_crit_chance=5,magical_crit_chance=5,dodge_chance=5,level=level)

def duel(a_cls,b_cls,trials=100,level=10,rarity="rare",seed=1462,healing=1.0,class_damage=None):
 class_damage=class_damage or {}; catalog=load_production_pvp_skill_catalog(); wins_a=wins_b=draws=0; rounds=[]; totals={"damage_a":0,"damage_b":0,"healing_a":0,"healing_b":0,"shield_a":0,"shield_b":0,"dot_a":0,"dot_b":0}
 with healing_multiplier(healing):
  for i in range(int(trials)):
   swap=bool(i%2); ca,cb=(b_cls,a_cls) if swap else (a_cls,b_cls); a=build_standard_actor(ca,level,rarity,1,class_damage.get(ca,1.0)); b=build_standard_actor(cb,level,rarity,2,class_damage.get(cb,1.0)); result=None; local={1:{"damage":0,"healing":0,"shield":0,"dot":0},2:{"damage":0,"healing":0,"shield":0,"dot":0}}
   for rnd in range(1,51):
    ia=choose_action(a,b,"target_aware",random.Random(seed+i*1000+rnd),catalog); ib=choose_action(b,a,"target_aware",random.Random(seed+i*1000+rnd+37),catalog)
    before={1:a,2:b}; result=resolve_pvp_round(rnd,rnd,a,b,ia,ib,seed=seed+i*1000+rnd,catalog=catalog)
    for outcome in result.outcomes:
     uid=int(outcome.user_id); local[uid]["damage"]+=int(outcome.damage or 0); local[uid]["healing"]+=int(outcome.healing or 0)
    for event in result.events:
     uid=int(event.get("user_id") or 0); kind=str(event.get("type") or ""); value=int(event.get("value") or 0)
     if uid in local and kind=="hot_tick": local[uid]["healing"]+=value
     elif uid in local and kind=="shield_absorb": local[uid]["shield"]+=value
     elif uid in local and kind=="dot_tick":
      key=str(event.get("effect") or ""); source_id=int(dict(before[uid].effects.get(key) or {}).get("source_id") or 0)
      if source_id in local: local[source_id]["dot"]+=value
    a=PvpActorState.from_dict(result.actor_a); b=PvpActorState.from_dict(result.actor_b)
    if result.terminal: break
   original_a_uid=2 if swap else 1; original_b_uid=1 if swap else 2
   if not result.winner_id: draws+=1
   elif int(result.winner_id)==original_a_uid: wins_a+=1
   elif int(result.winner_id)==original_b_uid: wins_b+=1
   else: raise AssertionError(f"unexpected winner_id={result.winner_id}")
   for metric in ("damage","healing","shield","dot"):
    totals[f"{metric}_a"]+=local[original_a_uid][metric]; totals[f"{metric}_b"]+=local[original_b_uid][metric]
   rounds.append(result.round_number)
 if wins_a+wins_b+draws!=int(trials): raise AssertionError(f"duel invariant failed: {wins_a}+{wins_b}+{draws}!={trials}")
 answer={"class_a":a_cls,"class_b":b_cls,"trials":int(trials),"level":level,"rarity":rarity,"healing_multiplier":healing,"class_damage":class_damage,"wins_a":wins_a,"wins_b":wins_b,"draws":draws,"win_rate_a":round(100*wins_a/int(trials),2),"win_rate_b":round(100*wins_b/int(trials),2),"avg_rounds":round(sum(rounds)/len(rounds),2)}
 for key,value in totals.items(): answer[f"avg_{key}"]=round(value/int(trials),2)
 return answer

def _actor_snapshot(class_key,level,rarity):
 actor=build_standard_actor(class_key,level,rarity); equipment={slot:_stats(class_key,slot,level,rarity) for slot in SLOTS}; equipment_primary={key:sum(int(item.get(key,0) or 0) for item in equipment.values()) for key in PRIMARY}; base={key:10+level-1 for key in PRIMARY}; final={key:base[key]+equipment_primary[key] for key in PRIMARY}
 return {"class_key":class_key,"label":LABELS[class_key],"level":actor.level,"rarity":rarity,"armor_profile":ARMOR[class_key],"base_primary_stats":base,"equipment_primary_stats":equipment_primary,"final_primary_stats":final,"equipment_breakdown":equipment,"max_hp":actor.max_hp,"max_mp":actor.max_mp,"physical_attack":actor.physical_attack,"magical_attack":actor.magical_attack,"physical_defense":actor.physical_defense,"magical_defense":actor.magical_defense,"weapon_physical_min":actor.weapon_physical_min,"weapon_physical_max":actor.weapon_physical_max,"weapon_magical_min":actor.weapon_magical_min,"weapon_magical_max":actor.weapon_magical_max,"resource_type":actor.resource_type,"resource":actor.resource,"equipment_slots":list(SLOTS)}

def _combat_signature(row):
 keys=("wins_a","wins_b","draws","avg_rounds","avg_damage_a","avg_damage_b","avg_healing_a","avg_healing_b","avg_shield_a","avg_shield_b","avg_dot_a","avg_dot_b")
 return {key:row.get(key) for key in keys}

def _sensitivity(trials,level,rarity,seed):
 configs=(("healing",("priest","knight"),{"healing":1.0},{"healing":0.4}),("warrior_damage",("warrior","knight"),{"class_damage":{"warrior":1.0}},{"class_damage":{"warrior":1.3}}),("scout_damage",("scout","rogue"),{"class_damage":{"scout":1.0}},{"class_damage":{"scout":1.3}})); checks=[]
 for index,(name,pair,base_kwargs,var_kwargs) in enumerate(configs):
  baseline=duel(pair[0],pair[1],trials,level,rarity,seed+index,**base_kwargs); variant=duel(pair[0],pair[1],trials,level,rarity,seed+index,**var_kwargs); a=_combat_signature(baseline); b=_combat_signature(variant); changed={key:{"baseline":a[key],"variant":b[key]} for key in a if a[key]!=b[key]}; checks.append({"parameter":name,"baseline_config":base_kwargs,"variant_config":var_kwargs,"combat_baseline":a,"combat_variant":b,"changed_combat_metrics":changed,"observable_change":bool(changed)})
 return {"checks":checks,"all_observable":all(row["observable_change"] for row in checks),"criterion":"combat_metrics_only_v2"}

def _slot_weighted_fixture_parity():
 weights={slot:float(SLOT_WEIGHTS[slot]) for slot in SLOTS if slot in SLOT_WEIGHTS}; failures=[]
 if set(SLOTS)!=set(SLOT_WEIGHTS): failures.append("slot set mismatch")
 total=round(sum(weights.values()),6)
 if total!=float(SLOT_WEIGHT_TOTAL): failures.append(f"weight total {total} != {SLOT_WEIGHT_TOTAL}")
 if weights.get("chest",0)<=weights.get("gloves",0): failures.append("chest weight must exceed gloves weight")
 if weights.get("main_hand",0)!=max(weights.values(),default=0): failures.append("main_hand must have the largest fixture weight")
 samples={class_key:{slot:{"weight":weights.get(slot),"stats":_stats(class_key,slot,10,"rare")} for slot in SLOTS} for class_key in CLASSES}
 return {"weights":weights,"weight_total":total,"expected_total":float(SLOT_WEIGHT_TOTAL),"slots_checked":len(weights),"samples_level_10_rare":samples,"failures":failures,"pass":not failures}

def _fixture_warnings(actors):
 hp=[x["max_hp"] for x in actors.values()]; attacks=[max(x["physical_attack"],x["magical_attack"]) for x in actors.values()]; hp_ratio=round(max(hp)/max(1,min(hp)),2); attack_ratio=round(max(attacks)/max(1,min(attacks)),2); warnings=[]
 if hp_ratio>1.6: warnings.append(f"HP max/min ratio {hp_ratio} > 1.60")
 if attack_ratio>1.6: warnings.append(f"Attack max/min ratio {attack_ratio} > 1.60")
 return {"hp_max_min_ratio":hp_ratio,"attack_max_min_ratio":attack_ratio,"warnings":warnings,"review":bool(warnings)}

def run_audit(trials=10,level=10,rarity="rare",seed=14622):
 trials=max(2,min(100,int(trials))); level=max(1,min(100,int(level)))
 if rarity not in RARITIES: raise ValueError("rarity must be common, uncommon or rare")
 actors={key:_actor_snapshot(key,level,rarity) for key in CLASSES}; skills=_skill_audit(); integrity=_matrix_integrity(trials,level,rarity,seed); sensitivity=_sensitivity(trials,level,rarity,seed+900000); fixtures=_fixture_warnings(actors); parity=_slot_weighted_fixture_parity(); verdict="PASS" if skills["pass"] and integrity["pass"] and parity["pass"] else "FAIL"
 return {"version":"14.6.2d","verdict":verdict,"trials":trials,"level":level,"rarity":rarity,"actors":actors,"skills":skills,"matrix_integrity":integrity,"modifier_sensitivity":sensitivity,"fixture_warnings":fixtures,"fixture_slot_parity":parity,"all_classes_checked":len(actors)==6,"all_skills_checked":skills["skills_checked"]==18,"live_balance_changed":False,"production_database_writes":0,"corrections_applied":False}

def _reference_analysis():
    rows = []
    for attacker in CLASSES:
        for defender in CLASSES:
            if attacker == defender:
                continue
            rows.append({"attacker":attacker,"defender":defender,"attack_type":PRODUCTION_REFERENCE[attacker]["weapon_type"],"expected_basic_damage":_expected_basic_damage(attacker,defender)})
    by_class = {}
    for key, row in PRODUCTION_REFERENCE.items():
        correct_defense_shape = (row["mdef"] > row["pdef"] if key in ("mage","priest") else row["pdef"] > row["mdef"] if key in ("warrior","knight") else True)
        dex_attack_gap = row["dex"] - row["physical_attack"] if key in ("scout","rogue") else 0
        by_class[key] = {**row,"defense_profile_expected":correct_defense_shape,"dex_minus_physical_attack":dex_attack_gap}
    return {"level":REFERENCE_LEVEL,"rarity":REFERENCE_RARITY,"classes":by_class,"expected_basic_damage_matrix":rows,"all_defense_profiles_expected":all(x["defense_profile_expected"] for x in by_class.values()),"dex_class_attack_review":any(by_class[x]["dex_minus_physical_attack"] >= 20 for x in ("scout","rogue"))}

def run_audit(trials=DEFAULT_TRIALS, level=10, rarity="rare", seed=14630):
    trials=max(10,min(500,int(trials))); level=max(1,min(100,int(level)))
    reference=_reference_analysis(); matchups=_matchup_audit(trials,level,rarity,seed)
    findings=[]
    if not reference["all_defense_profiles_expected"]: findings.append("production defense profile mismatch")
    if reference["dex_class_attack_review"]: findings.append("DEX classes have a large DEX versus physical_attack gap")
    if matchups["dominance_count"]: findings.append(f"{matchups['dominance_count']} matchup rows meet dominance review threshold")
    verdict="PASS_WITH_REVIEW" if findings else "PASS"
    return {"version":VERSION,"verdict":verdict,"trials":trials,"level":level,"rarity":rarity,"production_reference":reference,"matchup_dominance":matchups,"findings":findings,"live_balance_changed":False,"fixture_values_changed":False,"production_database_writes":0}

def normalize_refine_level(level):
    try:
        level = int(level)
    except Exception:
        level = 0
    return max(0, level)

def get_item_refine_kind(item_info):
    if not item_info:
        return ""
    category = item_info.get("category", "")
    slot_key = item_info.get("slot_key", "")
    type_ = item_info.get("type", "")
    if category != "equipment":
        return ""
    if slot_key == "main_hand" or type_ == "weapon":
        return "weapon"
    if slot_key in ARMOR_SLOT_KEYS:
        return "armor"
    return ""

def get_refine_max_level(refine_kind):
    if refine_kind == "weapon":
        return WEAPON_MAX_REFINE_LEVEL
    if refine_kind == "armor":
        return ARMOR_MAX_REFINE_LEVEL
    return 0

def get_refine_success_chance(refine_kind, current_level):
    current_level = normalize_refine_level(current_level)
    if refine_kind == "weapon":
        return WEAPON_REFINE_SUCCESS_CHANCES.get(current_level, 0)
    if refine_kind == "armor":
        return ARMOR_REFINE_SUCCESS_CHANCES.get(current_level, 0)
    return 0

def get_refine_failure_level(refine_kind, current_level):
    current_level = normalize_refine_level(current_level)
    if refine_kind == "weapon":
        return current_level if current_level <= 3 else max(0, current_level - 1)
    if refine_kind == "armor":
        return current_level if current_level <= 2 else max(0, current_level - 1)
    return current_level

def get_weapon_refine_damage_multiplier(refine_level):
    refine_level = min(normalize_refine_level(refine_level), WEAPON_MAX_REFINE_LEVEL)
    return WEAPON_REFINE_DAMAGE_MULTIPLIERS.get(refine_level, 1.00)

def apply_weapon_refine_to_damage(min_damage, max_damage, refine_level):
    multiplier = get_weapon_refine_damage_multiplier(refine_level)
    return int(round(int(min_damage or 0) * multiplier)), int(round(int(max_damage or 0) * multiplier))

def get_armor_refine_hp_bonus_percent(refine_level, rarity):
    refine_level = min(normalize_refine_level(refine_level), ARMOR_MAX_REFINE_LEVEL)
    rarity = (rarity or "common").strip().lower()
    base_bonus = ARMOR_REFINE_BASE_HP_BONUS_PERCENT.get(refine_level, 0.0)
    rarity_multiplier = ARMOR_REFINE_RARITY_HP_MULTIPLIERS.get(rarity, 1.0)
    return round(base_bonus * rarity_multiplier, 2)

def get_refine_display_suffix(refine_level):
    refine_level = normalize_refine_level(refine_level)
    return "" if refine_level <= 0 else f" [+{refine_level}]"

def can_refine_item(item_info):
    refine_kind = get_item_refine_kind(item_info)
    if not refine_kind:
        return {"success": False, "message": "❌ Цей предмет не можна заточити.", "refine_kind": ""}
    current_level = normalize_refine_level(item_info.get("refine_level", 0))
    max_level = get_refine_max_level(refine_kind)
    if current_level >= max_level:
        return {"success": False, "message": f"✅ Предмет уже має максимальну заточку +{max_level}.", "refine_kind": refine_kind}
    return {"success": True, "message": "✅ Предмет можна заточити.", "refine_kind": refine_kind, "current_level": current_level, "max_level": max_level}

def roll_refine_success(refine_kind, current_level, use_success_rune=False):
    if use_success_rune:
        return {"success": True, "chance": 100, "roll": None}
    chance = get_refine_success_chance(refine_kind, current_level)
    roll = random.randint(1, 100)
    return {"success": roll <= chance, "chance": chance, "roll": roll}

def perform_refine_attempt(user_id, inventory_id, use_success_rune=False, idempotency_key=None, db_path=None):
    """Atomically consume resources, apply refine result, and persist one attempt."""
    import json
    import sqlite3
    from datetime import datetime, timezone
    from pathlib import Path
    uid = int(user_id)
    inv_id = int(inventory_id)
    use_rune = bool(use_success_rune)
    key = str(idempotency_key or "").strip()
    if not key:
        return {"success": False, "message": "❌ Відсутній ключ операції заточки."}
    path = Path(db_path) if db_path is not None else Path(__file__).resolve().parents[1] / "game.db"
    conn = sqlite3.connect(str(path), timeout=30)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys=ON")
    conn.execute("PRAGMA busy_timeout=30000")
    try:
        conn.executescript("""CREATE TABLE IF NOT EXISTS refine_attempts(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            inventory_id INTEGER NOT NULL,
            item_id INTEGER NOT NULL,
            refine_kind TEXT NOT NULL,
            old_level INTEGER NOT NULL,
            new_level INTEGER NOT NULL,
            success_chance INTEGER NOT NULL,
            roll INTEGER,
            refine_success INTEGER NOT NULL,
            used_success_rune INTEGER NOT NULL,
            stone_quantity INTEGER NOT NULL DEFAULT 1,
            success_rune_quantity INTEGER NOT NULL DEFAULT 0,
            idempotency_key TEXT NOT NULL UNIQUE,
            created_at TEXT NOT NULL,
            FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE RESTRICT,
            FOREIGN KEY(item_id) REFERENCES items(id) ON DELETE RESTRICT
        );CREATE INDEX IF NOT EXISTS ix_refine_attempts_user ON refine_attempts(user_id,id DESC);""")
        conn.commit()
        conn.execute("BEGIN IMMEDIATE")
        old_attempt = conn.execute("SELECT * FROM refine_attempts WHERE idempotency_key=?", (key,)).fetchone()
        if old_attempt:
            conn.commit()
            row = dict(old_attempt)
            return {"success": True, "idempotent_replay": True, "refine_success": bool(row["refine_success"]), "refine_kind": row["refine_kind"], "old_level": row["old_level"], "new_level": row["new_level"], "chance": row["success_chance"], "roll": row["roll"], "used_success_rune": bool(row["used_success_rune"]), "message": "ℹ️ Цю спробу заточки вже виконано."}
        item = conn.execute("""SELECT inventory.id,inventory.user_id,inventory.item_id,COALESCE(inventory.refine_level,0) refine_level,items.name,items.type,items.category,items.slot_key,items.weapon_hands,items.item_subtype,items.armor_type FROM inventory JOIN items ON items.id=inventory.item_id WHERE inventory.id=?""", (inv_id,)).fetchone()
        if not item:
            conn.rollback(); return {"success": False, "message": "❌ Предмет не знайдено."}
        if int(item["user_id"]) != uid:
            conn.rollback(); return {"success": False, "message": "❌ Це не твій предмет."}
        info = dict(item)
        check = can_refine_item(info)
        if not check.get("success"):
            conn.rollback(); return check
        def total(item_id):
            return int(conn.execute("SELECT COALESCE(SUM(quantity),0) FROM inventory WHERE user_id=? AND item_id=? AND quantity>0", (uid,item_id)).fetchone()[0])
        if total(REFINE_STONE_ITEM_ID) < 1:
            conn.rollback(); return {"success": False, "message": "❌ Потрібен 🪨 Камінь Посилення."}
        if use_rune and total(SUCCESS_RUNE_ITEM_ID) < 1:
            conn.rollback(); return {"success": False, "message": "❌ Потрібна 💎 Руна Успіху."}
        def consume(item_id):
            row = conn.execute("SELECT id,quantity FROM inventory WHERE user_id=? AND item_id=? AND quantity>0 ORDER BY id LIMIT 1", (uid,item_id)).fetchone()
            if not row: raise RuntimeError("resource disappeared during refine")
            if int(row["quantity"]) == 1: conn.execute("DELETE FROM inventory WHERE id=? AND user_id=?", (int(row["id"]),uid))
            else: conn.execute("UPDATE inventory SET quantity=quantity-1 WHERE id=? AND user_id=? AND quantity>1", (int(row["id"]),uid))
            from db_modules.inventory import compact_user_item_stacks
            compact_user_item_stacks(uid, item_id, commit=False, connection=conn)
        kind = check["refine_kind"]
        current = int(check["current_level"])
        roll_result = roll_refine_success(kind,current,use_rune)
        new_level = current + 1 if roll_result["success"] else get_refine_failure_level(kind,current)
        consume(REFINE_STONE_ITEM_ID)
        if use_rune: consume(SUCCESS_RUNE_ITEM_ID)
        changed = conn.execute("UPDATE inventory SET refine_level=? WHERE id=? AND user_id=? AND COALESCE(refine_level,0)=?", (new_level,inv_id,uid,current)).rowcount
        if changed != 1: raise RuntimeError("refine target changed concurrently")
        now = datetime.now(timezone.utc).isoformat()
        conn.execute("INSERT INTO refine_attempts(user_id,inventory_id,item_id,refine_kind,old_level,new_level,success_chance,roll,refine_success,used_success_rune,stone_quantity,success_rune_quantity,idempotency_key,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)", (uid,inv_id,int(item["item_id"]),kind,current,new_level,int(roll_result["chance"]),roll_result["roll"],1 if roll_result["success"] else 0,1 if use_rune else 0,1,1 if use_rune else 0,key,now))
        max_level = WEAPON_MAX_REFINE_LEVEL if kind == "weapon" else ARMOR_MAX_REFINE_LEVEL
        if bool(roll_result["success"]) and current == max_level - 1 and new_level == max_level:
            from systems.world_chronicle_system import (
                get_character_name_snapshot,
                record_world_chronicle_event,
            )
            character_name = get_character_name_snapshot(uid, connection=conn)
            if character_name:
                record_world_chronicle_event(
                    "equipment_max_refine",
                    uid,
                    character_name,
                    f"equipment_max_refine:{inv_id}:{max_level}",
                    subject_key=str(item["item_id"]),
                    subject_name_snapshot=str(item["name"]),
                    metadata={"level": max_level},
                    connection=conn,
                )
        conn.commit()
        if roll_result["success"]: message=f"✅ Заточка успішна: +{current} → +{new_level}"
        elif new_level < current: message=f"❌ Заточка не вдалася: +{current} → +{new_level}"
        else: message=f"❌ Заточка не вдалася: +{current} без змін"
        return {"success": True, "idempotent_replay": False, "refine_success": bool(roll_result["success"]), "refine_kind": kind, "old_level": current, "new_level": new_level, "chance": int(roll_result["chance"]), "roll": roll_result["roll"], "used_success_rune": use_rune, "message": message}
    except Exception as error:
        try: conn.rollback()
        except Exception: pass
        return {"success": False, "message": f"❌ Заточку скасовано без списання ресурсів: {error}"}
    finally:
        conn.close()

def get_inventory_rune_socket_summary(inventory_id):
    runes = get_inventory_runes(inventory_id)
    capacity = get_inventory_rune_capacity(inventory_id)
    return {
        "inventory_id": int(inventory_id),
        "used": len(runes),
        "capacity": capacity,
        "free": max(0, capacity - len(runes)),
        "runes": runes,
    }

def validate_rune_fusion_selection(rune_item_ids):
    """Validate the future 3-rune recipe and return a user-facing reason."""
    try:
        selected = [int(item_id) for item_id in rune_item_ids]
    except Exception:
        selected = []
    if len(selected) != RUNE_FUSION_SOURCE_QUANTITY:
        return {
            "success": False,
            "code": "wrong_quantity",
            "message": "❌ Для переробки потрібно вибрати рівно 3 однакові руни.",
        }
    definitions = [get_rune_definition(item_id) for item_id in selected]
    if any(definition is None for definition in definitions):
        return {
            "success": False,
            "code": "not_rune",
            "message": "❌ Для переробки можна використовувати лише руни характеристик.",
        }
    keys = {(definition["stat"], definition["level"]) for definition in definitions}
    if len(keys) != 1:
