class SimulationProfile:
    key: str
    start_minute: int
    end_minute: int

    def __post_init__(self) -> None:
        if not self.key:
            raise ValueError("profile key is required")
        if not (0 <= self.start_minute < self.end_minute <= 24 * 60):
            raise ValueError("invalid active window")

    @property
    def active_minutes(self) -> int:
        return self.end_minute - self.start_minute

class SimulationConfig:
    character_class: str
    target_level: int = 20
    profile_key: str = "regular"
    seed: int = 1
    mode: str = "EXACT"
    inventory_capacity: int = 40
    inventory_reserve_slots: int = 2
    energy_max: int = 40
    energy_regen_minutes: int = 5
    hp_potion_threshold: float = 0.30
    mp_potion_threshold: float = 0.25
    repair_threshold: int = 10
    mob_level_delta: Tuple[int, ...] = (-1, 0, 1)
    combat_policy: str = "balanced"
    pvp_enabled: bool = False
    schema_version: str = "13.1.0"

    def __post_init__(self) -> None:
        allowed_classes = {"warrior", "knight", "scout", "rogue", "mage", "priest"}
        if self.character_class not in allowed_classes:
            raise ValueError("unsupported character class")
        if self.profile_key not in PROFILES:
            raise ValueError("unsupported simulation profile")
        if self.mode not in {"EXACT", "FAST"}:
            raise ValueError("mode must be EXACT or FAST")
        if not (1 <= self.target_level <= 30):
            raise ValueError("target_level must be in range 1..30")
        if self.inventory_capacity <= 0:
            raise ValueError("inventory_capacity must be positive")
        if not (0 <= self.inventory_reserve_slots < self.inventory_capacity):
            raise ValueError("invalid inventory reserve")
        if self.energy_max <= 0 or self.energy_regen_minutes <= 0:
            raise ValueError("invalid energy configuration")
        if not (0.0 <= self.hp_potion_threshold <= 1.0):
            raise ValueError("invalid HP potion threshold")
        if not (0.0 <= self.mp_potion_threshold <= 1.0):
            raise ValueError("invalid MP potion threshold")
        if self.repair_threshold < 0:
            raise ValueError("invalid repair threshold")
        if self.pvp_enabled:
            raise ValueError("PvP simulation is deferred until production PvP exists")

    @property
    def profile(self) -> SimulationProfile:
        return PROFILES[self.profile_key]

    def to_dict(self) -> Dict[str, Any]:
        data = asdict(self)
        data["mob_level_delta"] = list(self.mob_level_delta)
        data["profile"] = asdict(self.profile)
        return data

    def fingerprint(self) -> str:
        raw = json.dumps(self.to_dict(), ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        return sha256(raw.encode("utf-8")).hexdigest()

class SimulationDropInventoryEngine:
    def __init__(self,inventory,rng,item_resolver):self.inventory=inventory;self.rng=rng;self.item_resolver=item_resolver;self.inventory_engine=SimulationInventoryEngine(inventory)
    def roll_enemy(self,mob,rules=None):
        if rules is None:return drop_system.roll_enemy_drops(mob,self.rng.random)
        # Explicit simulation fixtures are rolled one by one. Full production-table
        # validation remains active when rules=None.
        return [drop_system.roll_drop_rule(rule,mob,self.rng.random) for rule in rules]
    def process_enemy(self,mob,rules=None):
        out=DropProcessResult()
        for row in self.roll_enemy(mob,rules):
            entry=dict(row);payload=entry.get('payload') or {};item_id=payload.get('item_id')
            if not entry.get('rolled') or item_id is None:out.results.append(entry);continue
            meta=dict(self.item_resolver(int(item_id)) or {})
            if not meta:out.results.append(entry);continue
            a=InventoryAward(int(item_id),str(meta.get('name',item_id)),str(meta.get('category','material')),int(payload.get('quantity',1)),int(meta.get('max_stack',1)),str(meta.get('slot_key','')),int(meta.get('item_level',1)),str(meta.get('rarity','common')),float(meta.get('sell_price',0)),meta)
            out.rolled+=a.quantity;applied=self.inventory_engine.award(a,True);entry['simulation_inventory']=asdict(applied)
            if applied.awarded:out.awarded+=applied.awarded;entry['awarded']=True;entry['lost']=False
            else:out.lost+=applied.lost;out.full_bag_events+=1;out.lost_value+=applied.lost*a.sell_price;entry['awarded']=False;entry['lost']=True;entry['reason']='inventory_full'
            out.results.append(entry)
        return out

