def normalize_skill(skill: dict[str, Any]) -> dict[str, Any]:
    keys = (
        "key", "name", "cost_type", "cost", "min_cost", "cooldown",
        "damage_multiplier", "attack_type", "effect", "duration",
        "stun_chance", "combo_gain", "consume_all", "spend_all",
        "resource_gain", "scaling", "scale_by_rage", "scale_by_combo",
        "scale_by_pdef",
    )
    return {key: skill.get(key) for key in keys if key in skill}

def inspect_skill_catalog(findings: list[dict[str, str]]) -> dict[str, Any]:
    candidates = [ROOT / "handlers/combat.py", ROOT / "handlers/combat_handler.py"]
    source_path = next((path for path in candidates if path.exists()), None)
    if source_path is None:
        findings.append({"severity": "BLOCKER", "code": "combat_handler_missing", "message": "Не знайдено handlers/combat.py або handlers/combat_handler.py"})
        return {"source": None, "classes": {}, "total_skills": 0}
    tree = ast.parse(source_path.read_text(encoding="utf-8"), filename=str(source_path))
    try:
        catalog = literal_assignment(tree, "CLASS_SKILLS_V1")
    except Exception as error:
        findings.append({"severity": "BLOCKER", "code": "skill_catalog_unreadable", "message": str(error)})
        return {"source": str(source_path.relative_to(ROOT)), "classes": {}, "total_skills": 0}
    if not isinstance(catalog, dict):
        findings.append({"severity": "BLOCKER", "code": "skill_catalog_type", "message": "CLASS_SKILLS_V1 має бути словником"})
        return {"source": str(source_path.relative_to(ROOT)), "classes": {}, "total_skills": 0}
    classes: dict[str, Any] = {}
    total = 0
    for class_key in EXPECTED_CLASSES:
        skills = catalog.get(class_key)
        if not isinstance(skills, (list, tuple)):
            findings.append({"severity": "BLOCKER", "code": "class_skills_missing", "message": f"{class_key}: відсутній список навичок"})
            skills = []
        if len(skills) != EXPECTED_SKILLS_PER_CLASS:
            findings.append({"severity": "BLOCKER", "code": "skill_count", "message": f"{class_key}: expected 3 skills, found {len(skills)}"})
        normalized = []
        keys_seen = set()
        for skill in skills:
            if not isinstance(skill, dict):
                findings.append({"severity": "BLOCKER", "code": "skill_type", "message": f"{class_key}: skill definition is not a dict"})
                continue
            missing = [key for key in ("key", "cost_type", "cooldown") if key not in skill]
            if missing:
                findings.append({"severity": "BLOCKER", "code": "skill_fields", "message": f"{class_key}/{skill.get('key', '?')}: missing {missing}"})
            skill_key = str(skill.get("key", ""))
            if skill_key in keys_seen:
                findings.append({"severity": "BLOCKER", "code": "duplicate_skill_key", "message": f"{class_key}: duplicate key {skill_key}"})
            keys_seen.add(skill_key)
            normalized.append(normalize_skill(skill))
        classes[class_key] = normalized
        total += len(normalized)
    extras = sorted(set(catalog) - set(EXPECTED_CLASSES))
    if extras:
        findings.append({"severity": "REVIEW", "code": "extra_skill_classes", "message": f"Unexpected classes in CLASS_SKILLS_V1: {extras}"})
    return {
        "source": str(source_path.relative_to(ROOT)),
        "source_sha256": sha256(source_path),
        "classes": classes,
        "total_skills": total,
        "expected_total": len(EXPECTED_CLASSES) * EXPECTED_SKILLS_PER_CLASS,
    }

def fingerprint(path):
    return (
        hashlib.sha256(path.read_bytes()).hexdigest(),
        path.stat().st_size,
        path.stat().st_mtime_ns,
    )

def logical_snapshot(conn):
    tables = [
        row[0] for row in conn.execute(
            "SELECT name FROM sqlite_master "
            "WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name"
        ).fetchall()
    ]
    result = {}
    for table in tables:
        quoted = '"' + table.replace('"', '""') + '"'
        columns = table_columns(conn, table)
        order = ", ".join(
            '"' + column.replace('"', '""') + '"' for column in columns
        ) or "rowid"
        rows = conn.execute(f"SELECT * FROM {quoted} ORDER BY {order}").fetchall()
        payload = json.dumps(
            [
                [value.hex() if isinstance(value, bytes) else value for value in row]
                for row in rows
            ],
            ensure_ascii=False,
            sort_keys=True,
            default=str,
        ).encode("utf-8")
        result[table] = {
            "rows": len(rows),
            "sha256": hashlib.sha256(payload).hexdigest(),
        }
    return result

def sha(path: Path):
    if not path.exists():
        return None
    h = hashlib.sha256()
    with path.open("rb") as f:
        for block in iter(lambda: f.read(1024 * 1024), b""):
            h.update(block)
    return {"size": path.stat().st_size, "sha256": h.hexdigest()}

def classify_function(module, node, module_imports):
    calls = []
    imports = set(module_imports)
    sql_reads = []
    sql_writes = []
    dynamic_sql = False
    flags = set()
    reasons = []

    for sub in ast.walk(node):
        if isinstance(sub, (ast.Import, ast.ImportFrom)):
            if isinstance(sub, ast.Import):
                imports.update(alias.name for alias in sub.names)
            else:
                imports.add(sub.module or "")
        elif isinstance(sub, ast.Call):
            name = dotted(sub.func)
            leaf = name.rsplit(".", 1)[-1]
            calls.append(name)
            if leaf in RNG_NAMES or name.startswith("random."):
                flags.add("GLOBAL_RNG_DEPENDENT")
            if leaf in TIME_NAMES or name.startswith(("datetime.", "date.", "time.")):
                flags.add("TIME_DEPENDENT")
            if leaf in TELEGRAM_NAMES or name.startswith(("bot.", "telebot.")):
                flags.add("TELEGRAM_DEPENDENT")
            if leaf in FILESYSTEM_NAMES and (name.startswith(("Path.", "pathlib.")) or leaf == "open"):
                flags.add("FILESYSTEM_DEPENDENT")
            if leaf in MUTATION_METHODS:
                flags.add("MUTATING_STATE")
            if leaf in READ_METHODS:
                flags.add("READS_STATE")
            if leaf in {"execute", "executemany", "executescript"}:
                text = literal_string(sub.args[0]) if sub.args else ""
                kind = sql_kind(text)
                if kind == "write":
                    flags.add("MUTATING_DB")
                    sql_writes.append(text[:240])
                elif kind == "read":
                    flags.add("READ_ONLY_DB")
                    sql_reads.append(text[:240])
                else:
                    dynamic_sql = True
                    flags.add("DB_DYNAMIC_SQL")
            if name.startswith(("db.", "sqlite3.")) or leaf in {"cursor", "connect"}:
                flags.add("DB_DEPENDENT")
        elif isinstance(sub, ast.Global):
            flags.add("GLOBAL_STATE_DEPENDENT")
        elif isinstance(sub, (ast.Assign, ast.AugAssign, ast.AnnAssign)):
            targets = sub.targets if isinstance(sub, ast.Assign) else [sub.target]
            for target in targets:
                if isinstance(target, ast.Subscript) and isinstance(target.value, ast.Name):
                    if target.value.id.isupper() or target.value.id.endswith("STATE"):
                        flags.add("GLOBAL_STATE_MUTATION")

    if any(x == "telebot" or x.startswith("telebot.") for x in imports):
        flags.add("TELEGRAM_MODULE")
    if module == "db.py":
        flags.add("LEGACY_FACADE_OR_MONOLITH")
    if "MUTATING_DB" in flags or ("DB_DEPENDENT" in flags and "MUTATING_STATE" in flags):
        flags.add("ADAPTER_REQUIRED")
    if "TELEGRAM_DEPENDENT" in flags or "TELEGRAM_MODULE" in flags:
        flags.add("ADAPTER_REQUIRED")
    if "GLOBAL_RNG_DEPENDENT" in flags:
        flags.add("RNG_INJECTION_REQUIRED")
    if "TIME_DEPENDENT" in flags:
        flags.add("CLOCK_INJECTION_REQUIRED")

    pure_blockers = flags & {
        "MUTATING_DB", "READ_ONLY_DB", "DB_DEPENDENT", "DB_DYNAMIC_SQL",
        "TELEGRAM_DEPENDENT", "TELEGRAM_MODULE", "FILESYSTEM_DEPENDENT",
        "GLOBAL_STATE_DEPENDENT", "GLOBAL_STATE_MUTATION", "GLOBAL_RNG_DEPENDENT", "TIME_DEPENDENT",
    }
    if not pure_blockers:
        flags.add("PURE_CANDIDATE")
        safe = True
        action = "Використовувати напряму після parity-тесту."
    elif pure_blockers <= {"GLOBAL_RNG_DEPENDENT"}:
        safe = True
        action = "Додати ін'єкцію seeded RNG; формулу не дублювати."
    elif pure_blockers <= {"TIME_DEPENDENT"}:
        safe = True
        action = "Додати SimulationClock."
    elif "MUTATING_DB" in flags or "TELEGRAM_DEPENDENT" in flags or "GLOBAL_STATE_MUTATION" in flags:
        safe = False
        action = "Не викликати на real DB; потрібен simulation adapter або pure rule extraction."
    elif "READ_ONLY_DB" in flags or "DB_DEPENDENT" in flags:
        safe = False
        action = "Винести обчислення в pure rule, дані передавати через SimulationState."
    else:
        safe = False
        action = "Потрібен ручний review перед підключенням."

    if module.startswith("handlers/") or module == "main.py":
        safe = False
        flags.add("PRESENTATION_OR_ENTRYPOINT")
        action = "Не використовувати в engine; лише окремий DEV handler для запуску та звітів."

    return {
        "module": module,
        "function": node.name,
        "async": isinstance(node, ast.AsyncFunctionDef),
        "line_range": line_range(node),
        "args": [a.arg for a in node.args.args],
        "classification": sorted(flags),
        "safe_for_exact_simulation": bool(safe),
        "recommended_action": action,
        "calls": sorted(set(c for c in calls if c))[:120],
        "sql_reads": sql_reads[:20],
        "sql_writes": sql_writes[:20],
        "dynamic_sql": dynamic_sql,
    }

def analyze_module(path: Path, rel: str):
    source = path.read_text(encoding="utf-8-sig")
    tree = ast.parse(source, filename=rel)
    imports = set()
    module_effects = []
    functions = []
    for node in tree.body:
        if isinstance(node, ast.Import):
            imports.update(alias.name for alias in node.names)
        elif isinstance(node, ast.ImportFrom):
            imports.add(node.module or "")
        elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            functions.append(classify_function(rel, node, imports))
        elif isinstance(node, (ast.Expr, ast.Assign, ast.AnnAssign, ast.AugAssign, ast.For, ast.While, ast.With, ast.Try)):
            for sub in ast.walk(node):
                if isinstance(sub, ast.Call):
                    name = dotted(sub.func)
                    if name and name not in {"globals", "getattr", "hasattr", "setattr", "len", "str", "int", "float", "list", "dict", "tuple", "set"}:
                        module_effects.append({"call": name, "line": getattr(sub, "lineno", 0)})
    return {
        "module": rel,
        "sha256": sha(path)["sha256"],
        "size": path.stat().st_size,
        "imports": sorted(imports),
        "module_scope_calls": module_effects[:100],
        "functions": functions,
    }

def top_level_sql_side_effects(tree):
    findings = []
    mutating_methods = {"execute", "executemany", "executescript", "commit", "rollback"}
    mutating_names = {
        "ensure_refine_material_stack_sizes",
        "migrate_active_contracts_target_kills_to_5",
        "run_pending_migrations",
        "seed_items",
        "seed_location_trash_items",
        "seed_class_reset_sphere_item",
    }
    for statement in tree.body:
        if isinstance(statement, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef,
                                  ast.Import, ast.ImportFrom)):
            continue
        for node in ast.walk(statement):
            if not isinstance(node, ast.Call):
                continue
            name = None
            if isinstance(node.func, ast.Name):
                name = node.func.id
            elif isinstance(node.func, ast.Attribute):
                name = node.func.attr
            if name in mutating_methods or name in mutating_names:
                findings.append({"line": node.lineno, "call": name})
    return findings

def project_code_references():
    references = defaultdict(list)
